+++ w/internal/ui/oci_resources/browser_flow.go
@@ -97,6 +97,8 @@ func (b *RegistryBrowser) startImageSearch(query string, entries []browserRegist
 	// A new search starts from the default order and without the previous
 	// confirmed `/` filter (DEVDESK-309).
 	b.searchTable.FilterBar().ClearSearch()
+	b.searchFilter = resultFilter{}
+	b.syncSearchFilterToken()
 	b.searchTable.SetSort(-1, false)
 	b.searchTable.SetItems(nil)

diff --git i/internal/ui/oci_resources/browser_images.go w/internal/ui/oci_resources/browser_images.go
index af50d52e..157e31c5 100644
--- i/internal/ui/oci_resources/browser_images.go
+++ w/internal/ui/oci_resources/browser_images.go
@@ -13,6 +13,7 @@ import (
 	"github.com/anthnel/devdesk/internal/imagesearch"
 	"github.com/anthnel/devdesk/internal/jobs"
 	"github.com/anthnel/devdesk/internal/oci"
+	"github.com/anthnel/devdesk/internal/ui/components"
 	"github.com/anthnel/devdesk/internal/ui/datatable"
 	"github.com/anthnel/devdesk/internal/ui/indicator"
 	"github.com/anthnel/devdesk/internal/ui/shortcut"
@@ -110,24 +111,62 @@ func newSearchTable() *datatable.Model[searchRow] {

 // rebuildSearchTable hands the collected images to the table.
 func (b *RegistryBrowser) rebuildSearchTable() {
-	rows := make([]searchRow, len(b.images))
-	for i, img := range b.images {
+	rows := make([]searchRow, 0, len(b.images))
+	for _, img := range b.images {
+		if !b.searchFilter.matches(img.EntryKey, b.entryFor(img.EntryKey)) {
+			continue
+		}
 		label, ref := "", img.Repo
 		if e := b.entryFor(img.EntryKey); e != nil {
 			label = b.entryLabel(img.EntryKey)
 			ref = searchRowReference(e.URL, img)
 		}
-		rows[i] = searchRow{img: img, label: label, ref: ref}
+		rows = append(rows, searchRow{img: img, label: label, ref: ref})
 	}
 	sortSearchRows(b.searchQuery, rows)
 	// Nothing selected (an empty table, so also a new search) goes to the
 	// first row, because an empty table keeps its old cursor index.
 	prev, hadSel := b.searchTable.Selected()
+	b.syncSearchFilterToken()
 	b.searchTable.SetItems(rows)
 	b.reselect(prev, hadSel)
 	b.resizeTables()
 }

+// syncSearchFilterToken shows the `r` filter as an active token in the bar, and
+// removes it when the filter is off. The table has no configured tokens, so the
+// token only makes the bar visible and labels it; rows are prefiltered above.
+func (b *RegistryBrowser) syncSearchFilterToken() {
+	if b.searchFilter.isEmpty() {
+		b.searchTable.FilterBar().SetTokens(nil)
+		return
+	}
+	b.searchTable.FilterBar().SetTokens([]components.FilterToken{{Label: b.filterLabel(b.searchFilter), Active: true}})
+}
+
+// searchFilterStops returns the stops `r` cycles through on level 1: the
+// lot's registries, in form order, that have at least one image row.
+func (b *RegistryBrowser) searchFilterStops() []resultFilter {
+	has := make(map[string]bool, len(b.images))
+	for _, img := range b.images {
+		has[img.EntryKey] = true
+	}
+	var keys []string
+	for _, k := range b.searchKeys {
+		if has[k] {
+			keys = append(keys, k)
+		}
+	}
+	return b.filterStopsFor(keys)
+}
+
+// cycleSearchRegistryFilter advances `r` on level 1; the cursor follows its
+// row through rebuildSearchTable.
+func (b *RegistryBrowser) cycleSearchRegistryFilter() {
+	b.searchFilter = nextFilter(b.searchFilterStops(), b.searchFilter)
+	b.rebuildSearchTable()
+}
+
 // reselect puts the cursor back on the row prev, by (EntryKey, Repo) and not by
 // index: rows of another registry land before or after it, and a sort moves it.
 // Without a previous selection the cursor goes to the first row; a vanished row
@@ -193,6 +232,9 @@ func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrow
 	case ".":
 		b.cycleSearchSort()
 		return b, nil
+	case "r":
+		b.cycleSearchRegistryFilter()
+		return b, nil
 	case "right":
 		return b.openSelectedImageTags()
 	case "esc":
diff --git i/internal/ui/oci_resources/browser_tags.go w/internal/ui/oci_resources/browser_tags.go
index 2a6d8ba6..7c7f9284 100644
--- i/internal/ui/oci_resources/browser_tags.go
+++ w/internal/ui/oci_resources/browser_tags.go
@@ -9,30 +9,50 @@ import (
 	"github.com/anthnel/devdesk/internal/oci"
 )

-// filterStops returns the values `r` cycles through: every group that produced
-// results, then every individual registry, then off. The group level is what
-// makes "everything from this Nexus" one keystroke rather than eight.
+// filterStops returns the values `r` cycles through for the tags tab.
 func (b *RegistryBrowser) filterStops() []resultFilter {
+	keys := make([]string, len(b.tags))
+	for i, t := range b.tags {
+		keys[i] = t.EntryKey
+	}
+	return b.filterStopsFor(keys)
+}
+
+// filterStopsFor returns the values `r` cycles through for results coming from
+// the given entry keys, in order of first appearance: every group that
+// produced results, then every individual registry, then off. The group level
+// is what makes "everything from this Nexus" one keystroke rather than eight.
+// Repeated keys collapse.
+func (b *RegistryBrowser) filterStopsFor(keys []string) []resultFilter {
 	seenGroup, seenEntry := map[string]bool{}, map[string]bool{}
 	var groups, singles []resultFilter
-	for _, t := range b.tags {
-		entry := b.entryFor(t.EntryKey)
+	for _, key := range keys {
+		entry := b.entryFor(key)
 		if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
 			seenGroup[entry.ParentSlug] = true
 			groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
 		}
-		if !seenEntry[t.EntryKey] {
-			seenEntry[t.EntryKey] = true
-			singles = append(singles, resultFilter{entryKey: t.EntryKey})
+		if !seenEntry[key] {
+			seenEntry[key] = true
+			singles = append(singles, resultFilter{entryKey: key})
 		}
 	}
 	// A single source has nothing to filter down to.
 	if len(singles) <= 1 {
 		return nil
 	}
-	// A group with every result under it says the same thing as "off".
-	if len(groups) == 1 && len(groups) == len(seenGroup) && len(singles) == countMembers(b.entries, groups[0].groupSlug) {
-		groups = nil
+	// A group holding every result and every member says the same as "off".
+	if len(groups) == 1 {
+		n := countMembers(b.entries, groups[0].groupSlug)
+		inGroup := 0
+		for _, f := range singles {
+			if e := b.entryFor(f.entryKey); e != nil && e.ParentSlug == groups[0].groupSlug {
+				inGroup++
+			}
+		}
+		if inGroup == len(singles) && len(singles) == n {
+			groups = nil
+		}
 	}
 	return append(groups, singles...)
 }
@@ -49,30 +69,28 @@ func countMembers(entries []browserRegistryEntry, slug string) int {
 }

 func (b *RegistryBrowser) cycleRegistryFilter() {
-	stops := b.filterStops()
+	b.registryFilter = nextFilter(b.filterStops(), b.registryFilter)
+	b.rebuildTagTable()
+}
+
+// nextFilter returns the stop after cur: off goes to the first stop, the last
+// stop and any unknown filter go back to off.
+func nextFilter(stops []resultFilter, cur resultFilter) resultFilter {
 	if len(stops) == 0 {
-		b.registryFilter = resultFilter{}
-		b.rebuildTagTable()
-		return
+		return resultFilter{}
 	}
-	if b.registryFilter.isEmpty() {
-		b.registryFilter = stops[0]
-		b.rebuildTagTable()
-		return
+	if cur.isEmpty() {
+		return stops[0]
 	}
 	for i, s := range stops {
-		if s == b.registryFilter {
+		if s == cur {
 			if i+1 < len(stops) {
-				b.registryFilter = stops[i+1]
-			} else {
-				b.registryFilter = resultFilter{} // back to everything
+				return stops[i+1]
 			}
-			b.rebuildTagTable()
-			return
+			return resultFilter{}
 		}
 	}
-	b.registryFilter = resultFilter{}
-	b.rebuildTagTable()
+	return resultFilter{}
 }

