package ociresources

import (
	"slices"
	"testing"
)

func TestNextFilter(t *testing.T) {
	g := resultFilter{groupSlug: "prod"}
	a := resultFilter{entryKey: "a"}
	c := resultFilter{entryKey: "c"}
	stops := []resultFilter{g, a, c}
	tests := []struct {
		name  string
		stops []resultFilter
		cur   resultFilter
		want  resultFilter
	}{
		{"no stops, off", nil, resultFilter{}, resultFilter{}},
		{"no stops, a stale filter goes off", nil, a, resultFilter{}},
		{"off goes to the first stop", stops, resultFilter{}, g},
		{"a stop goes to the next", stops, g, a},
		{"the middle stop goes to the next", stops, a, c},
		{"the last stop goes back to off", stops, c, resultFilter{}},
		{"an unknown filter goes off", stops, resultFilter{entryKey: "zzz"}, resultFilter{}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := nextFilter(tt.stops, tt.cur); got != tt.want {
				t.Errorf("nextFilter = %+v, want %+v", got, tt.want)
			}
		})
	}
}

func TestFilterStopsForTwoGroups(t *testing.T) {
	b := &RegistryBrowser{entries: []browserRegistryEntry{
		{key: "a1", Slug: "ga", ParentSlug: "ga"},
		{key: "a2", Slug: "ga", ParentSlug: "ga"},
		{key: "b1", Slug: "gb", ParentSlug: "gb"},
		{key: "b2", Slug: "gb", ParentSlug: "gb"},
	}}
	e := func(k string) resultFilter { return resultFilter{entryKey: k} }
	want := []resultFilter{{groupSlug: "ga"}, {groupSlug: "gb"}, e("a1"), e("a2"), e("b1"), e("b2")}
	if got := b.filterStopsFor([]string{"a1", "a2", "b1", "b2"}); !slices.Equal(got, want) {
		t.Errorf("filterStopsFor = %+v, want %+v", got, want)
	}
}

func TestFilterStopsFor(t *testing.T) {
	b := &RegistryBrowser{entries: []browserRegistryEntry{
		{key: "hub", Slug: "hub"},
		{key: "m1", Slug: "prod", ParentSlug: "prod"},
		{key: "m2", Slug: "prod", ParentSlug: "prod"},
		{key: "m3", Slug: "prod", ParentSlug: "prod"},
		{key: "solo", Slug: "solo"},
	}}
	g := resultFilter{groupSlug: "prod"}
	e := func(k string) resultFilter { return resultFilter{entryKey: k} }
	tests := []struct {
		name string
		keys []string
		want []resultFilter
	}{
		{"no key", nil, nil},
		{"one key", []string{"hub"}, nil},
		{"one key repeated", []string{"hub", "hub"}, nil},
		{"two lone registries", []string{"hub", "solo"}, []resultFilter{e("hub"), e("solo")}},
		{"a group and a foreign registry", []string{"m1", "m2", "hub"}, []resultFilter{g, e("m1"), e("m2"), e("hub")}},
		{"partial members, no foreign key, keep the group", []string{"m1", "m2"}, []resultFilter{g, e("m1"), e("m2")}},
		{"a group covering every member is dropped", []string{"m1", "m2", "m3"}, []resultFilter{e("m1"), e("m2"), e("m3")}},
		{"the order follows the keys", []string{"solo", "hub"}, []resultFilter{e("solo"), e("hub")}},
		{"duplicates collapse", []string{"hub", "solo", "hub", "solo"}, []resultFilter{e("hub"), e("solo")}},
		{"an unknown key is a registry", []string{"hub", "ghost"}, []resultFilter{e("hub"), e("ghost")}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := b.filterStopsFor(tt.keys); !slices.Equal(got, tt.want) {
				t.Errorf("filterStopsFor(%v) = %+v, want %+v", tt.keys, got, tt.want)
			}
		})
	}
}
package ociresources

import (
	"slices"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/imagesearch"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-310 (IS-06) step 5: `r` on level 1 narrows the image list to one
// group or one registry. Black box: keys in, rows, header, footer and bar out.
// The `r` shortcut entry and the help text belong to step 6, not tested here.

const (
	rfWidth = 180
	rfDesc  = "Bitnami packaged"
)

var (
	rfM1  = memberKey("prod", "registry.example.com", "docker-hosted")
	rfM2  = memberKey("prod", "registry.example.com", "dhi-proxy")
	rfHub = "hub"
)

// rfSearchModel starts a level 1 search over the group prod (members m1, m2)
// and the lone registry hub, in that form order. No answer has arrived yet.
func rfSearchModel(t *testing.T) (Model, *fakeSearcher) {
	t.Helper()
	fake := &fakeSearcher{}
	withImageSearcher(t, fake)
	return searchLot(t, groupedModel(t)), fake
}

func rfImage(name, desc string) []imagesearch.Image {
	return []imagesearch.Image{{Name: name, Repo: name, Description: desc}}
}

// rfAnswered has m1 "nginx", m2 "redis" and hub "nginx-hub" in the table.
func rfAnswered(t *testing.T) (Model, *fakeSearcher) {
	t.Helper()
	m, fake := rfSearchModel(t)
	m = answerFor(t, m, rfM1, rfImage("nginx", ""), false, nil)
	m = answerFor(t, m, rfM2, rfImage("redis", ""), false, nil)
	m = answerFor(t, m, rfHub, rfImage("nginx-hub", ""), false, nil)
	if m.registryBrowser.pendingSearches != 0 {
		t.Fatalf("fixture: pendingSearches = %d", m.registryBrowser.pendingSearches)
	}
	return m, fake
}

func rfNames(m Model) []string {
	names := lvl1Names(m)
	slices.Sort(names)
	return names
}

func rfWantNames(t *testing.T, m Model, want ...string) {
	t.Helper()
	slices.Sort(want)
	if got := rfNames(m); !slices.Equal(got, want) {
		t.Fatalf("rows = %q, want %q", got, want)
	}
}

func rfBar(m Model) string { return ansi.Strip(m.registryBrowser.FilterBarView(rfWidth)) }

// AC2: `r` goes through the group, each registry, then off.
func TestRCyclesTheGroupEachRegistryThenOffOnLevelOne(t *testing.T) {
	m, _ := rfAnswered(t)
	b := m.registryBrowser
	if m.GetFooterHeight() != 2 {
		t.Fatalf("fixture: footer height = %d, want 2", m.GetFooterHeight())
	}

	steps := []struct {
		label string
		rows  []string
	}{
		{b.filterLabel(resultFilter{groupSlug: "prod"}), []string{"nginx", "redis"}},
		{b.filterLabel(resultFilter{entryKey: rfM1}), []string{"nginx"}},
		{b.filterLabel(resultFilter{entryKey: rfM2}), []string{"redis"}},
		{b.filterLabel(resultFilter{entryKey: rfHub}), []string{"nginx-hub"}},
	}
	for i, s := range steps {
		m = feed(t, m, testutil.Key("r"))
		rfWantNames(t, m, s.rows...)
		if !b.FilterIsVisible() {
			t.Errorf("stop %d: the bar is hidden", i)
		}
		if !strings.Contains(rfBar(m), "["+s.label+"]") && !strings.Contains(rfBar(m), s.label) {
			t.Errorf("stop %d: token %q missing in the bar %q", i, s.label, rfBar(m))
		}
		if got := m.GetFooterHeight(); got != 4 {
			t.Errorf("stop %d: footer height = %d, want 4", i, got)
		}
		if got := lvl1Header(t, m, "Images"); got != itoa(len(s.rows)) {
			t.Errorf("stop %d: Images = %q, want %d", i, got, len(s.rows))
		}
	}
	m = feed(t, m, testutil.Key("r"))
	rfWantNames(t, m, "nginx", "redis", "nginx-hub")
	if b.FilterIsVisible() {
